11	// ============ Type Converters ============
12	
13	function snakeToCamel(str: string): string {
14	  return str.replace(/_([a-z])/g, (_, letter) => letter.toUpperCase());
15	}
16	
17	function convertKeysToCamel<T extends Record<string, unknown>>(obj: T): Record<string, unknown> {
18	  const result: Record<string, unknown> = {};
19	  for (const key in obj) {
20	    if (Object.prototype.hasOwnProperty.call(obj, key)) {
21	      result[snakeToCamel(key)] = obj[key];
22	    }
23	  }
24	  return result;
25	}
