/**
 * Stripe Router — checkout sessions, billing portal, invoices, plans
 */
import { router } from "../_core/trpc";
import { governedPublicProcedure, governedProtectedProcedure } from "../governance/trpc-enforcement";
import { z } from "zod";
import { TRPCError } from "@trpc/server";
import * as db from "../supabase-adapter";
import { createCheckoutSession, createBillingPortalSession, getInvoices } from "../stripe/checkout";
import { GRAVITO_PLANS, GRAVITO_CHECKOUT_PLAN_KEYS, getGravitoPlanDetails } from "../stripe/gravito-plans";
import { getCurrentUsageSummary } from "../billing/governed-usage-meter";
import { getApiKeysByUserId } from "../db";
import { createGravitoCheckoutSession, createGravitoBillingPortalSession } from "../stripe/gravito-checkout";
import { PLANS, CHECKOUT_PLAN_KEYS } from "../stripe/products";
import { ENV } from '../_core/env';
import { isTrustedBrowserOrigin } from '../_core/public-origin-allowlist';
import { stripeLog } from '../_core/logger';
import { pricingPreview, AccountType } from '../../shared/billing-engine';

const publicProcedure = governedPublicProcedure;
const protectedProcedure = governedProtectedProcedure;
// Payment mutations use protected governance (auth + basic checks).
// Structural integrity enforcement is for content mutations, not payment actions.
// A customer paying should never be blocked by an internal code quality score.
const highStakesProcedure = governedProtectedProcedure;

/**
 * R6-SEC-002: Validate Origin header against known domains to prevent
 * open-redirect via forged Origin in Stripe checkout success/cancel URLs.
 */
function getSafeOrigin(req: { headers: { origin?: string; host?: string } }): string {
  const origin = req.headers.origin;
  if (origin && isTrustedBrowserOrigin(origin)) {
    return origin;
  }
  // Fallback: construct from Host header (trusted by reverse proxy)
  const host = req.headers.host;
  if (host) {
    const protocol = host.includes('localhost') ? 'http' : 'https';
    return `${protocol}://${host}`;
  }
  return ENV.appUrl;
}

export const stripeRouter = router({
  plans: publicProcedure.query(() => {
    return Object.entries(PLANS).map(([key, plan]) => ({
      key,
      ...plan,
      price: (plan.price ?? 0) / 100,
    }));
  }),

  createCheckout: highStakesProcedure
    .input(z.object({
      plan: z.enum(CHECKOUT_PLAN_KEYS),
    }))
    .mutation(async ({ ctx, input }) => {
      const origin = getSafeOrigin(ctx.req);

      const session = await createCheckoutSession({
        userId: ctx.user!.id,
        userEmail: ctx.user!.email || "",
        userName: ctx.user!.name || undefined,
        plan: input.plan,
        origin,
      });

      return { url: session.url };
    }),

  createPortalSession: protectedProcedure.mutation(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user.id);

    if (!subscription?.stripeCustomerId) {
      throw new TRPCError({
        code: "NOT_FOUND",
        message: "No billing information found",
      });
    }

    const origin = getSafeOrigin(ctx.req);
    const session = await createBillingPortalSession({
      customerId: subscription.stripeCustomerId,
      origin,
    });

    return { url: session.url };
  }),

  invoices: protectedProcedure.query(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user.id);

    if (!subscription?.stripeCustomerId) {
      return [];
    }

    const invoices = await getInvoices(subscription.stripeCustomerId);
    return invoices.map(inv => ({
      id: inv.id,
      amount: (inv.amount_paid || 0) / 100,
      status: inv.status,
      date: inv.created ? new Date(inv.created * 1000) : null,
      invoiceUrl: inv.hosted_invoice_url,
      pdfUrl: inv.invoice_pdf,
    }));
  }),

  gravitoPlans: publicProcedure.query(() => {
    return Object.entries(GRAVITO_PLANS).map(([key, plan]) => ({
      key,
      name: plan.name,
      description: plan.description,
      tagline: plan.tagline,
      monthlyPrice: plan.monthlyPrice,
      annualPrice: plan.annualMonthlyPrice,
      includedChecks: plan.includedChecks,
      overageRate: plan.overageRate,
      features: plan.features,
      highlight: plan.highlight,
      sla: plan.sla,
      roiMessage: plan.roiMessage,
      cta: plan.cta,
    }));
  }),

  createGravitoCheckout: highStakesProcedure
    .input(z.object({
      plan: z.enum(GRAVITO_CHECKOUT_PLAN_KEYS),
      annual: z.boolean().default(false),
      // UTM attribution fields (optional)
      scanSessionId: z.string().optional(),
      utmSource: z.string().optional(),
      utmMedium: z.string().optional(),
      utmCampaign: z.string().optional(),
      utmContent: z.string().optional(),
      scannedUrl: z.string().optional(),
      scanScore: z.number().optional(),
      scanGrade: z.string().optional(),
    }))
    .mutation(async ({ ctx, input }) => {
      const origin = getSafeOrigin(ctx.req);

      const session = await createGravitoCheckoutSession({
        userId: ctx.user!.id,
        userEmail: ctx.user!.email || "",
        userName: ctx.user!.name || undefined,
        plan: input.plan,
        annual: input.annual,
        origin,
      });

      // Capture conversion event with UTM attribution
      try {
        const { captureConversionEvent } = await import("../governance/scan-attribution");
        await captureConversionEvent({
          sessionId: input.scanSessionId,
          email: ctx.user!.email || undefined,
          url: input.scannedUrl,
          utmSource: input.utmSource,
          utmMedium: input.utmMedium,
          utmCampaign: input.utmCampaign,
          utmContent: input.utmContent,
          plan: input.plan,
          billingCycle: input.annual ? "annual" : "monthly",
          stripeSessionId: session.id,
          userId: ctx.user!.id,
          score: input.scanScore,
          grade: input.scanGrade,
        });
      } catch (e) {
        stripeLog.warn({ err: e }, 'Failed to capture conversion event');
      }

      return { url: session.url };
    }),

  createGravitoPortalSession: protectedProcedure.mutation(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user.id);

    if (!subscription?.stripeCustomerId) {
      throw new TRPCError({
        code: "NOT_FOUND",
        message: "No billing information found",
      });
    }

    const origin = getSafeOrigin(ctx.req);
    const session = await createGravitoBillingPortalSession({
      customerId: subscription.stripeCustomerId,
      origin,
    });

    return { url: session.url };
  }),

  /**
   * Get checkout result — called by /checkout/success page.
   * Returns the user's current plan, API keys, and usage summary.
   */
  getCheckoutResult: protectedProcedure.query(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user.id);
    const apiKeys = await getApiKeysByUserId(ctx.user.id);
    const plan = subscription?.plan || null;
    const planDetails = plan ? getGravitoPlanDetails(plan) : null;

    return {
      plan,
      planName: planDetails?.name || plan || "Unknown",
      planDescription: planDetails?.description || null,
      status: subscription?.status || "inactive",
      stripeCustomerId: subscription?.stripeCustomerId || null,
      apiKeys: apiKeys.map(k => ({
        id: k.id,
        prefix: k.keyPrefix,
        name: k.name,
        isActive: k.isActive,
        createdAt: k.createdAt,
      })),
      hasApiKey: apiKeys.length > 0,
    };
  }),

  /**
   * Public pricing preview — cost calculator for the pricing page.
   * No auth required. Returns projected monthly cost based on estimated usage.
   */
  pricingPreview: publicProcedure
    .input(z.object({
      estimatedStandardChecks: z.number().min(0).max(50_000_000),
      estimatedRegulatedChecks: z.number().min(0).max(10_000_000),
      accountType: z.enum(['developer', 'team', 'business', 'enterprise', 'builder', 'startup', 'company', 'regulated_enterprise']),
    }))
    .query(({ input }) => {
      return pricingPreview({
        estimatedStandardChecks: input.estimatedStandardChecks,
        estimatedRegulatedChecks: input.estimatedRegulatedChecks,
        accountType: input.accountType as AccountType,
      });
    }),

  /**
   * Get current usage summary for the billing dashboard.
   */
  getUsageSummary: protectedProcedure.query(async ({ ctx }) => {
    const subscription = await db.getSubscriptionByUserId(ctx.user.id);
    const summary = await getCurrentUsageSummary({
      stripeCustomerId: subscription?.stripeCustomerId || undefined,
      userId: ctx.user.id,
    });
    return summary;
  }),
});

