/**
 * UserDashboard — The core product experience after signup.
 * Shows: plan status, API keys, usage stats, quick start checklist, billing.
 *
 * Uses real tRPC procedures:
 *   - trpc.apiKeys.list / create / delete / regenerate
 *   - trpc.usage.stats
 *   - trpc.subscription.current / billingHistory
 *   - trpc.stripe.createCheckout / billingPortal
 */
import { useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { toast } from "sonner";
import { Link } from "wouter";
import {
  Key, BarChart3, CreditCard, Zap, Copy, Trash2, RefreshCw,
  Plus, CheckCircle2, Circle, ExternalLink, ChevronRight,
  Activity, Shield, Code2, BookOpen, ArrowUpRight, Eye, EyeOff,
  AlertCircle, Loader2
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Progress } from "@/components/ui/progress";
import {
  Dialog, DialogContent, DialogDescription, DialogFooter,
  DialogHeader, DialogTitle, DialogTrigger
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

const PLAN_COLORS: Record<string, string> = {
  free: "bg-slate-100 text-slate-700",
  developer: "bg-blue-100 text-blue-700",
  team: "bg-violet-100 text-violet-700",
  business: "bg-blue-100 text-blue-700",
  enterprise: "bg-emerald-100 text-emerald-700",
  builder: "bg-blue-100 text-blue-700",
  startup: "bg-violet-100 text-violet-700",
};

const PLAN_LIMITS: Record<string, number> = {
  free: 100,
  developer: 1000,
  team: 10000,
  business: 100000,
  enterprise: -1,
  builder: 15000,
  startup: 75000,
};

function QuickStartChecklist({ hasApiKey, hasUsage }: { hasApiKey: boolean; hasUsage: boolean }) {
  const steps = [
    { done: true, label: "Create your account", link: null },
    { done: hasApiKey, label: "Generate your first API key", link: "#api-keys" },
    { done: hasUsage, label: "Make your first governance check", link: "/docs/quickstart" },
    { done: false, label: "Integrate with your AI pipeline", link: "/docs" },
    { done: false, label: "Set up Slack alerts", link: "/settings/slack" },
  ];

  const completed = steps.filter(s => s.done).length;

  return (
    <Card className="border-border/50">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base font-semibold">Getting Started</CardTitle>
          <span className="text-xs text-muted-foreground">{completed}/{steps.length} complete</span>
        </div>
        <Progress value={(completed / steps.length) * 100} className="h-1.5" />
      </CardHeader>
      <CardContent className="space-y-2">
        {steps.map((step, i) => (
          <div key={i} className="flex items-center gap-3">
            {step.done
              ? <CheckCircle2 className="h-4 w-4 text-emerald-500 shrink-0" />
              : <Circle className="h-4 w-4 text-muted-foreground/40 shrink-0" />
            }
            {step.link && !step.done ? (
              <Link href={step.link} className="text-sm text-primary hover:underline flex items-center gap-1">
                {step.label} <ChevronRight className="h-3 w-3" />
              </Link>
            ) : (
              <span className={`text-sm ${step.done ? "text-muted-foreground line-through" : "text-foreground"}`}>
                {step.label}
              </span>
            )}
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

function ApiKeyCard({ apiKey, onDelete, onRegenerate }: {
  apiKey: { id: number; keyPrefix: string; name: string | null; isActive: boolean; createdAt: Date; lastUsedAt: Date | null };
  onDelete: (id: number) => void;
  onRegenerate: (id: number) => void;
}) {
  const [showFull, setShowFull] = useState(false);
  const displayKey = showFull ? `${apiKey.keyPrefix}${"•".repeat(32)}` : `${apiKey.keyPrefix}••••••••`;

  return (
    <div className="flex items-center justify-between p-3 rounded-lg border border-border/50 bg-muted/20 hover:bg-muted/40 transition-colors">
      <div className="flex items-center gap-3 min-w-0">
        <Key className="h-4 w-4 text-muted-foreground shrink-0" />
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className="text-sm font-medium truncate">{apiKey.name || "Unnamed key"}</span>
            <Badge variant={apiKey.isActive ? "default" : "secondary"} className="text-xs h-4">
              {apiKey.isActive ? "active" : "inactive"}
            </Badge>
          </div>
          <div className="flex items-center gap-2 mt-0.5">
            <code className="text-xs text-muted-foreground font-mono">{displayKey}</code>
            <button onClick={() => setShowFull(!showFull)} className="text-muted-foreground hover:text-foreground">
              {showFull ? <EyeOff className="h-3 w-3" /> : <Eye className="h-3 w-3" />}
            </button>
          </div>
          <p className="text-xs text-muted-foreground mt-0.5">
            Created {new Date(apiKey.createdAt).toLocaleDateString()}
            {apiKey.lastUsedAt && ` · Last used ${new Date(apiKey.lastUsedAt).toLocaleDateString()}`}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-1 shrink-0">
        <Button
          variant="ghost" size="icon" className="h-7 w-7"
          onClick={() => { navigator.clipboard.writeText(apiKey.keyPrefix); toast.success("Key prefix copied"); }}
        >
          <Copy className="h-3.5 w-3.5" />
        </Button>
        <Button
          variant="ghost" size="icon" className="h-7 w-7"
          onClick={() => onRegenerate(apiKey.id)}
        >
          <RefreshCw className="h-3.5 w-3.5" />
        </Button>
        <Button
          variant="ghost" size="icon" className="h-7 w-7 text-destructive hover:text-destructive"
          onClick={() => onDelete(apiKey.id)}
        >
          <Trash2 className="h-3.5 w-3.5" />
        </Button>
      </div>
    </div>
  );
}

/**
 * ApiKeyRevealDialog — the ONE reliable moment a user can see their full key.
 *
 * The server only stores a hash, so the plaintext is unrecoverable after this.
 * A transient toast was too easy to miss; this is a persistent dialog with a
 * copy button, a shown-once warning, and a selectable monospace field.
 */
function ApiKeyRevealDialog({ apiKey, onClose }: { apiKey: string | null; onClose: () => void }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    if (!apiKey) return;
    try {
      await navigator.clipboard.writeText(apiKey);
      setCopied(true);
      toast.success("Copied to clipboard");
      setTimeout(() => setCopied(false), 2000);
    } catch {
      toast.error("Couldn't copy — select the key and copy it manually.");
    }
  };

  const close = () => {
    setCopied(false);
    onClose();
  };

  return (
    <Dialog open={!!apiKey} onOpenChange={(open) => { if (!open) close(); }}>
      <DialogContent onEscapeKeyDown={(e) => e.preventDefault()}>
        <DialogHeader>
          <DialogTitle>Your new API key</DialogTitle>
          <DialogDescription>
            Copy your key now and store it somewhere safe.
          </DialogDescription>
        </DialogHeader>

        <div className="flex items-start gap-2 rounded-md border border-blue-200 bg-blue-50 p-3">
          <AlertCircle className="h-4 w-4 text-blue-600 mt-0.5 shrink-0" />
          <p className="text-xs font-medium text-blue-700">
            Save this key now — you won't be able to see it again. We only store a
            hashed copy, so it can't be recovered later.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Input
            readOnly
            aria-label="Your new API key"
            value={apiKey ?? ""}
            className="font-mono text-xs"
            onFocus={(e) => e.currentTarget.select()}
          />
          <Button
            type="button" variant="outline" size="icon"
            aria-label="Copy API key"
            onClick={handleCopy}
          >
            {copied ? <CheckCircle2 className="h-4 w-4 text-emerald-500" /> : <Copy className="h-4 w-4" />}
          </Button>
        </div>

        <DialogFooter>
          <Button onClick={close}>Done</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export default function UserDashboard() {
  const { user, loading: authLoading } = useAuth();
  const [newKeyName, setNewKeyName] = useState("");
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [revealedKey, setRevealedKey] = useState<string | null>(null);
  const utils = trpc.useUtils();

  // Data fetching
  const { data: apiKeys, isLoading: keysLoading } = trpc.apiKeys.list.useQuery(undefined, { enabled: !!user });
  const { data: usageStats, isLoading: usageLoading } = trpc.usage.stats.useQuery(undefined, { enabled: !!user });
  const { data: subscription } = trpc.subscription.current.useQuery(undefined, { enabled: !!user });
  const { data: billingHistory, isLoading: billingLoading } = trpc.subscription.billingHistory.useQuery(undefined, { enabled: !!user });

  // Mutations
  const createKey = trpc.apiKeys.create.useMutation({
    onSuccess: (data) => {
      utils.apiKeys.list.invalidate();
      setCreateDialogOpen(false);
      setNewKeyName("");
      if (data) {
        setRevealedKey(data.key);
        toast.success("API key created");
      } else {
        toast.error("Key created, but we couldn't retrieve it. Please regenerate it to get a usable key.");
      }
    },
    onError: (err) => toast.error(err.message),
  });

  const deleteKey = trpc.apiKeys.delete.useMutation({
    onSuccess: () => { utils.apiKeys.list.invalidate(); toast.success("API key deleted"); },
    onError: (err) => toast.error(err.message),
  });

  const regenerateKey = trpc.apiKeys.regenerate.useMutation({
    onSuccess: (data) => {
      utils.apiKeys.list.invalidate();
      if (data) {
        setRevealedKey(data.key);
        toast.success("API key regenerated");
      } else {
        toast.error("Couldn't regenerate the key. Please try again.");
      }
    },
    onError: (err) => toast.error(err.message),
  });

  const _createCheckout = trpc.stripe.createGravitoCheckout.useMutation({
    onSuccess: (data) => {
      if (data.url) window.open(data.url, "_blank");
    },
    onError: (err) => toast.error(err.message),
  });

  const openBillingPortal = trpc.stripe.createGravitoPortalSession.useMutation({
    onSuccess: (data) => {
      if (data.url) window.open(data.url, "_blank");
    },
    onError: (err) => toast.error(err.message),
  });

  if (authLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center space-y-4">
          <AlertCircle className="h-10 w-10 text-muted-foreground mx-auto" />
          <p className="text-muted-foreground">Please log in to access your dashboard.</p>
          <Button asChild><Link href="/login">Log in</Link></Button>
        </div>
      </div>
    );
  }

  const plan = subscription?.plan || "free";
  const planLimit = PLAN_LIMITS[plan] ?? 100;
  const usageTotal = usageStats?.total ?? 0;
  const usagePct = planLimit > 0 ? Math.min(100, Math.round((usageTotal / planLimit) * 100)) : 0;
  const hasApiKey = (apiKeys?.length ?? 0) > 0;
  const hasUsage = usageTotal > 0;

  return (
    <div className="min-h-screen bg-background">
      {/* Header */}
      <div className="border-b border-border/50 bg-card/50">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Link href="/" className="flex items-center gap-2 text-foreground hover:text-primary transition-colors">
              <Shield className="h-5 w-5 text-primary" />
              <span className="font-semibold text-sm">Gravito</span>
            </Link>
            <span className="text-muted-foreground/40">/</span>
            <span className="text-sm text-muted-foreground">Dashboard</span>
          </div>
          <div className="flex items-center gap-3">
            <Badge className={`text-xs ${PLAN_COLORS[plan] || "bg-slate-100 text-slate-700"}`}>
              {plan.charAt(0).toUpperCase() + plan.slice(1)} plan
            </Badge>
            <span className="text-sm text-muted-foreground hidden sm:block">{user.name || user.email}</span>
          </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 sm:px-6 py-8 space-y-6">
        {/* Welcome + Stats Row */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <Card className="border-border/50">
            <CardContent className="pt-4">
              <div className="flex items-center gap-2 text-muted-foreground mb-1">
                <Activity className="h-4 w-4" />
                <span className="text-xs font-medium uppercase tracking-wide">Checks this month</span>
              </div>
              {usageLoading ? (
                <div className="h-8 w-24 bg-muted animate-pulse rounded" />
              ) : (
                <div className="flex items-end gap-2">
                  <span className="text-2xl font-bold">{usageTotal.toLocaleString()}</span>
                  {planLimit > 0 && (
                    <span className="text-xs text-muted-foreground mb-1">/ {planLimit.toLocaleString()}</span>
                  )}
                </div>
              )}
              {planLimit > 0 && !usageLoading && (
                <Progress value={usagePct} className="h-1 mt-2" />
              )}
            </CardContent>
          </Card>

          <Card className="border-border/50">
            <CardContent className="pt-4">
              <div className="flex items-center gap-2 text-muted-foreground mb-1">
                <Shield className="h-4 w-4" />
                <span className="text-xs font-medium uppercase tracking-wide">Gates blocked</span>
              </div>
              {usageLoading ? (
                <div className="h-8 w-16 bg-muted animate-pulse rounded" />
              ) : (
                <span className="text-2xl font-bold">{(usageStats?.gatesBlocked ?? 0).toLocaleString()}</span>
              )}
              <p className="text-xs text-muted-foreground mt-1">Policy violations caught</p>
            </CardContent>
          </Card>

          <Card className="border-border/50">
            <CardContent className="pt-4">
              <div className="flex items-center gap-2 text-muted-foreground mb-1">
                <BarChart3 className="h-4 w-4" />
                <span className="text-xs font-medium uppercase tracking-wide">Avg score</span>
              </div>
              {usageLoading ? (
                <div className="h-8 w-16 bg-muted animate-pulse rounded" />
              ) : (
                <span className="text-2xl font-bold">
                  {usageStats?.averageScore ? `${Math.round(usageStats.averageScore * 100)}%` : "—"}
                </span>
              )}
              <p className="text-xs text-muted-foreground mt-1">Governance quality score</p>
            </CardContent>
          </Card>

          <Card className="border-border/50">
            <CardContent className="pt-4">
              <div className="flex items-center gap-2 text-muted-foreground mb-1">
                <Key className="h-4 w-4" />
                <span className="text-xs font-medium uppercase tracking-wide">API keys</span>
              </div>
              {keysLoading ? (
                <div className="h-8 w-10 bg-muted animate-pulse rounded" />
              ) : (
                <span className="text-2xl font-bold">{apiKeys?.length ?? 0}</span>
              )}
              <p className="text-xs text-muted-foreground mt-1">Active integrations</p>
            </CardContent>
          </Card>
        </div>

        {/* Main Content */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left: Tabs */}
          <div className="lg:col-span-2">
            <Tabs defaultValue="api-keys" id="api-keys">
              <TabsList className="grid grid-cols-3 w-full">
                <TabsTrigger value="api-keys" className="gap-1.5">
                  <Key className="h-3.5 w-3.5" /> API Keys
                </TabsTrigger>
                <TabsTrigger value="usage" className="gap-1.5">
                  <BarChart3 className="h-3.5 w-3.5" /> Usage
                </TabsTrigger>
                <TabsTrigger value="billing" className="gap-1.5">
                  <CreditCard className="h-3.5 w-3.5" /> Billing
                </TabsTrigger>
              </TabsList>

              {/* API Keys Tab */}
              <TabsContent value="api-keys" className="mt-4 space-y-3">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="text-sm font-semibold">API Keys</h3>
